-- Contacts and consent for texts and WhatsApp (docs/plan.md §1.19, §1.22): a contact per client with
-- consent per channel and an opt-out, an append-only log of their changes, `contact` as a message
-- sender (a contact's thread holds what they sent and what we sent them), and the messages count in
-- usage_daily. New tables, a widened check and a column with a default, so the previous Worker keeps
-- working. Generated by drizzle-kit; the grants, row-level security and append-only trigger at the
-- end are hand-written, as in 0002, 0004 and 0005.
CREATE TABLE "contact" (
	"id" uuid PRIMARY KEY DEFAULT uuid_generate_v7() NOT NULL,
	"tenant_id" uuid NOT NULL,
	"name" text NOT NULL,
	"phone" text,
	"whatsapp" text,
	"language" text,
	"consent" jsonb DEFAULT '{}'::jsonb NOT NULL,
	"opted_out_at" timestamp with time zone,
	"opt_out_source" text,
	"created_by" uuid,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "contact_id_tenant_key" UNIQUE("id","tenant_id"),
	CONSTRAINT "contact_reachable_check" CHECK ("contact"."phone" is not null or "contact"."whatsapp" is not null),
	CONSTRAINT "contact_opt_out_check" CHECK (("contact"."opted_out_at" is null) = ("contact"."opt_out_source" is null))
);
